CREATE TYPE "UserStatus" AS ENUM ('ACTIVE', 'LOCKED', 'DISABLED');
CREATE TYPE "AuditOutcome" AS ENUM ('SUCCESS', 'FAILURE', 'DENIED');
CREATE TABLE "establishments" ("id" UUID PRIMARY KEY, "legal_name" TEXT NOT NULL, "trade_name" TEXT NOT NULL, "tax_id" TEXT NOT NULL UNIQUE, "timezone" TEXT NOT NULL DEFAULT 'America/Bogota', "currency" TEXT NOT NULL DEFAULT 'COP', "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "branches" ("id" UUID PRIMARY KEY, "establishment_id" UUID NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "branches_establishment_id_fkey" FOREIGN KEY ("establishment_id") REFERENCES "establishments"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "branches_establishment_id_code_key" ON "branches"("establishment_id", "code");
CREATE INDEX "branches_establishment_id_active_idx" ON "branches"("establishment_id", "active");
CREATE TABLE "terminals" ("id" UUID PRIMARY KEY, "branch_id" UUID NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "fingerprint" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "terminals_branch_id_fkey" FOREIGN KEY ("branch_id") REFERENCES "branches"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "terminals_branch_id_code_key" ON "terminals"("branch_id", "code"); CREATE UNIQUE INDEX "terminals_fingerprint_key" ON "terminals"("fingerprint");
CREATE TABLE "users" ("id" UUID PRIMARY KEY, "establishment_id" UUID NOT NULL, "email" TEXT NOT NULL, "display_name" TEXT NOT NULL, "password_hash" TEXT NOT NULL, "status" "UserStatus" NOT NULL DEFAULT 'ACTIVE', "failed_login_count" INTEGER NOT NULL DEFAULT 0, "locked_until" TIMESTAMPTZ(3), "last_login_at" TIMESTAMPTZ(3), "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "users_establishment_id_fkey" FOREIGN KEY ("establishment_id") REFERENCES "establishments"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "users_establishment_id_email_key" ON "users"("establishment_id", "email"); CREATE INDEX "users_establishment_id_status_idx" ON "users"("establishment_id", "status");
CREATE TABLE "roles" ("id" UUID PRIMARY KEY, "code" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "system" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "permissions" ("id" UUID PRIMARY KEY, "code" TEXT NOT NULL UNIQUE, "description" TEXT NOT NULL);
CREATE TABLE "user_roles" ("user_id" UUID NOT NULL, "role_id" UUID NOT NULL, PRIMARY KEY ("user_id", "role_id"), FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE, FOREIGN KEY ("role_id") REFERENCES "roles"("id") ON DELETE CASCADE);
CREATE TABLE "role_permissions" ("role_id" UUID NOT NULL, "permission_id" UUID NOT NULL, PRIMARY KEY ("role_id", "permission_id"), FOREIGN KEY ("role_id") REFERENCES "roles"("id") ON DELETE CASCADE, FOREIGN KEY ("permission_id") REFERENCES "permissions"("id") ON DELETE CASCADE);
CREATE TABLE "refresh_sessions" ("id" UUID PRIMARY KEY, "user_id" UUID NOT NULL, "token_hash" TEXT NOT NULL, "expires_at" TIMESTAMPTZ(3) NOT NULL, "revoked_at" TIMESTAMPTZ(3), "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE);
CREATE INDEX "refresh_sessions_user_id_expires_at_idx" ON "refresh_sessions"("user_id", "expires_at");
CREATE TABLE "audit_logs" ("id" BIGSERIAL PRIMARY KEY, "establishment_id" UUID NOT NULL, "user_id" UUID, "action" TEXT NOT NULL, "entity_type" TEXT NOT NULL, "entity_id" TEXT, "outcome" "AuditOutcome" NOT NULL, "reason" TEXT, "ip_address" TEXT, "metadata" JSONB, "occurred_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY ("establishment_id") REFERENCES "establishments"("id") ON DELETE RESTRICT, FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE SET NULL);
CREATE INDEX "audit_logs_establishment_id_occurred_at_idx" ON "audit_logs"("establishment_id", "occurred_at" DESC); CREATE INDEX "audit_logs_user_id_occurred_at_idx" ON "audit_logs"("user_id", "occurred_at" DESC);
